import re

def parse(lines):
    w = re.compile(r'^(?P<file>\S.*?):(?P<line>\d+): (?P<category>\w+): (?P<message>.*)$')
    hint = re.compile(r'^(?P<category>\w+(?:Warning|Error)): (?P<message>.*)$')
    rows, idx, notes, nidx, skip = [], [], [], [], []
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = w.match(l)
        if m:
            cur = {'file': m.group('file'), 'line': int(m.group('line')), 'category': m.group('category'), 'message': m.group('message').strip(), 'source': ''}
            rows.append(cur)
            idx.append(i)
            continue
        if l[:1] in (' ', '\t') and cur is not None:
            if cur['source'] == '':
                cur['source'] = l.strip()
            else:
                cur['source'] += '\n' + l.strip()
            idx.append(i)
            continue
        m = hint.match(l)
        if m:
            notes.append({'category': m.group('category'), 'message': m.group('message').strip()})
            nidx.append(i)
            cur = None
            continue
        skip.append(i)
    blocks = [{'name': 'warnings', 'kind': 'table', 'lines': idx, 'records': rows}]
    if notes:
        blocks.append({'name': 'notes', 'kind': 'table', 'lines': nidx, 'records': notes})
    return {'blocks': blocks, 'skip': skip}
